import {gameUnits,gameDecimal} from './mind-game.mjs';
const check=(ok,code,message)=>{if(!ok)throw Object.assign(new Error(message),{code});};
const n=v=>{const value=gameUnits(v);check(value>=0n,'LIVE_POSITION_LEDGER','원장 금액을 확인하세요.');return value;},d=gameDecimal,iso=v=>{check(Number.isFinite(Date.parse(v)),'LIVE_POSITION_TIME','체결 시각을 확인하세요.');return new Date(v).toISOString();},copy=structuredClone;
export function replayLiveAutomationFills(rows,{marketIds,asOf}){
 const groups=new Map();
 for(const row of rows){const order=JSON.parse(row.order_body);if(order.purpose==='FUNDING')continue;check(marketIds.includes(order.request.market),'LIVE_POSITION_MARK_SCOPE','운용 종목과 체결 원장을 대조하세요.');const t={...JSON.parse(row.trade_body),_sequence:row.fill_sequence},group=groups.get(order.identifier)??{order,fee:n(row.applied_fee),trades:[]};group.trades.push(t);groups.set(order.identifier,group);}
 const fills=[];for(const {order,fee,trades}of groups.values()){trades.sort((x,y)=>Date.parse(x.createdAt)-Date.parse(y.createdAt)||x.id.localeCompare(y.id));const total=trades.reduce((sum,t)=>sum+n(t.funds),0n);let allocated=0n;for(let i=0;i<trades.length;i++){const trade=trades[i],part=i===trades.length-1?fee-allocated:total?fee*n(trade.funds)/total:0n;allocated+=part;fills.push({trade,order,fee:part});}}
 fills.sort((x,y)=>Date.parse(x.trade.createdAt)-Date.parse(y.trade.createdAt)||x.trade._sequence-y.trade._sequence);let realized=0n,fees=0n;const ledger=[],assets={};for(const {trade,order,fee}of fills){const at=iso(trade.createdAt),q=n(trade.volume),gross=n(trade.funds),buy=order.request.side==='bid',name=order.request.market.split('-')[1],p=assets[name]??={quantity:0n,basis:0n};check(at<=asOf,'LIVE_POSITION_TIME','결정 시각 이전의 실제 체결을 확인하세요.');let pnl=0n;if(buy){p.quantity+=q;p.basis+=gross+fee;}else{check(q<=p.quantity,'LIVE_POSITION_LEDGER','실제 체결 수량과 보유량을 대조하세요.');const removed=p.basis*q/p.quantity;p.quantity-=q;p.basis-=removed;pnl=gross-removed-fee;}realized+=pnl;fees+=fee;ledger.push({runId:trade.id,exchangeTradeId:trade.id,exchangeOrderIdentifier:order.identifier,at,side:buy?'buy':'sell',quantity:Number(d(q)),fillPrice:Number(trade.price),fee:Number(d(fee)),realizedPnl:Number(d(pnl)),exactRealizedPnl:d(pnl),exactFee:d(fee),instrumentId:'crypto:upbit:'+order.request.market,feeAllocation:'ACTUAL_ORDER_PAID_FEE_PROPORTIONAL_FUNDS',mode:'live',intent:copy(order.plan?.signalEvidence?.intent??null)});}
 return {ledger,assets,realized,fees};
}
